/**
 * Reads / clears the investor's saved payment method. The card token itself is captured
 * server-side when a payment completes and is never exposed here — this only surfaces the
 * masked card for display and lets the investor remove the saved card.
 */
@Injectable({ providedIn: 'root' })
export class PaymentMethodApiService {
  private baseUrl = `${environment.apiBaseUrl}/Investor`;

  constructor(private http: HttpClient) {}

  get(investorId: number): Observable<InvestorPaymentMethod> {
    return this.http
      .get<any>(`${this.baseUrl}/GetPaymentMethod/${investorId}`)
      .pipe(map(r => this.normalize(r)));
  }

  remove(investorId: number): Observable<void> {
    return this.http.delete<void>(`${this.baseUrl}/DeletePaymentMethod?investorId=${investorId}`);
  }

  // ASP.NET Core may serialize camelCase or PascalCase; accept both.
  private normalize(raw: any): InvestorPaymentMethod {
    return {
      hasSavedCard:  raw?.hasSavedCard  ?? raw?.HasSavedCard  ?? false,
      maskedCard:    raw?.maskedCard    ?? raw?.MaskedCard    ?? null,
      cardType:      raw?.cardType      ?? raw?.CardType      ?? null,
      paymentSystem: raw?.paymentSystem ?? raw?.PaymentSystem ?? null,
      tokenLifetime: raw?.tokenLifetime ?? raw?.TokenLifetime ?? null,
      iban:          raw?.iban          ?? raw?.Iban          ?? null
    };
  }
}
import { ScheduleType } from './product.model';

export enum ServiceTokenStatus {
  None      = 0,
  Available = 1,
  Sold      = 2,
  InCart    = 3,
  Finished  = 255
}

export enum OwnerType {
  Company = 0,
  Investor = 1
}

export interface ServiceToken {
  id: string;
  rowVersion: number;
  companyId: number;
  requestId: number;
  productId: number;
  startDate: string;
  endDate?: string | null;
  status: ServiceTokenStatus | number;
  remainingCount: number;
  serviceCount: number;
  scheduleType: ScheduleType;
  ownerType: OwnerType | number;
  ownerPublicKey: string;
}

export interface ServiceTokenDto extends ServiceToken {
  companyName: string;
  productName: string;
  price: number;
  pictogram?: string | null; // base64-encoded image from API
  term?: number | null;
}
export interface Investor {
  id: number;
  rowVersion: number;
  publicKey: string;
  status: number;
  userName: string;
  password: string;
}

export interface AdminUser {
  id: number;
  userName: string;
  userFullName: string;
  password: string;
}
// Models for the Flitt embedded checkout flow (mirrors the .NET PaymentController DTOs).

/** Result of initiating a payment: the order id we poll on, and the Flitt checkout token. */
export interface InitiateEmbeddedPaymentResult {
  orderId: string;
  token: string;
}

/** A single token reference sent when initiating a (possibly multi-token) payment. */
export interface PaymentTokenRef {
  serviceTokenId: string;
  rowVersion: number;
}

// Mirrors the backend PaymentStatus enum (serialized as its name string).
export type PaymentStatusValue =
  | 'None'
  | 'Created'
  | 'Processing'
  | 'Succeeded'
  | 'Failed'
  | 'Expired'
  | 'Cancelled';

/** Per-token outcome inside a payment order. */
export interface PaymentItemStatus {
  serviceTokenId: string;
  status: PaymentStatusValue | string;
}

/**
 * Status of a (possibly multi-token) payment order. One Flitt order can now cover several
 * tokens, so the response carries an overall headline `status`, a `final` flag (true only once
 * every token is terminal — the signal the client polls on) and the per-token `items`.
 */
export interface PaymentBatchStatusResult {
  orderId: string;
  status: PaymentStatusValue | string;
  final: boolean;
  amount: number;
  currency: string;
  items: PaymentItemStatus[];
}

const FINAL_PAYMENT_STATUSES: ReadonlyArray<string> =
  ['Succeeded', 'Failed', 'Expired', 'Cancelled'];

/** True once a single token/order has reached a terminal state. */
export function isFinalStatus(status: string): boolean {
  return FINAL_PAYMENT_STATUSES.includes(status);
}

/** True only when funds were captured and ownership was finalized. */
export function isSuccessStatus(status: string): boolean {
  return status === 'Succeeded';
}
export interface LoginCredentialDto {
  userName: string;
  password: string;
}

// Matches ServiceTokenApi.Dto.CompanyRequestDto
export interface CompanyRequestDto {
  name: string;
  taxCode: string;
  userName: string;
  password: string;
}

// Matches ServiceTokenApi.Dto.InvestorCreateDto (entity fields)
export interface InvestorCreateDto {
  publicKey: string;
  userName: string;
  password: string;
}

// Matches ServiceTokenApi.Dto.RequestDto
export interface RequestDto {
  companyId: number;
  productId: number;
  serviceTokenCount: number;
}

