import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink, ActivatedRoute } from '@angular/router';
import { InvestorApiService } from '../../../core/api/investor-api.service';
import { InvestorStateService } from '../../../core/state/investor-state.service';
import { InvestorCreateDto } from '../../../shared/models/dtos.model';
import { ToastService } from '../../../core/services/toast.service';

@Component({
  selector: 'app-investor-login',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './investor-login.component.html',
  styleUrls: ['./investor-login.component.scss']
})
export class InvestorLoginComponent implements OnInit {
  isRegisterMode = false;

  loginModel = { userName: '', password: '' };
  registerModel: InvestorCreateDto = { publicKey: '', userName: '', password: '' };

  loading = false;
  loginError = '';

  private toast = inject(ToastService);

  constructor(
    private investorApi: InvestorApiService,
    private investorState: InvestorStateService,
    private router: Router,
    private route: ActivatedRoute
  ) {}

  ngOnInit(): void {
    this.route.queryParams.subscribe(params => {
      if (params['mode'] === 'register') {
        this.isRegisterMode = true;
      }
    });
  }

  toggleMode() {
    this.isRegisterMode = !this.isRegisterMode;
    this.loginError = '';
  }

  onLogin() {
    this.loading = true;
    this.loginError = '';
    this.investorApi.login(this.loginModel).subscribe({
      next: investor => {
        this.loading = false;
        this.investorState.investor = investor;
        const pendingId = this.investorState.pendingTokenId;
        if (pendingId) {
          this.router.navigate(['/marketplace'], { queryParams: { tab: 'primaryMarket', openToken: pendingId } });
        } else {
          this.router.navigate(['/marketplace']);
        }
      },
      error: () => {
        this.loading = false;
        this.loginError = 'Incorrect username or password. Please try again.';
      }
    });
  }

  onRegister() {
    this.loading = true;
    this.investorApi.register(this.registerModel).subscribe({
      next: _ => {
        this.loading = false;
        this.toast.success('Registration successful! You can now login with your credentials.');
        this.isRegisterMode = false;
      },
      error: err => { this.loading = false; this.toast.error(err.error?.message ?? err.error); }
    });
  }
}
import { Injectable } from '@angular/core';
import { Investor } from '../../shared/models/user.model';

const SESSION_KEY = 'investor_session';

@Injectable({ providedIn: 'root' })
export class InvestorStateService {
  private _investor: Investor | null = null;

  constructor() {
    // Rehydrate from sessionStorage on startup (survives F5, cleared on tab close)
    try {
      const stored = sessionStorage.getItem(SESSION_KEY);
      if (stored) this._investor = JSON.parse(stored);
    } catch { /* ignore */ }
  }

  get investor(): Investor | null {
    return this._investor;
  }

  set investor(value: Investor | null) {
    this._investor = value;
    try {
      if (value) sessionStorage.setItem(SESSION_KEY, JSON.stringify(value));
      else sessionStorage.removeItem(SESSION_KEY);
    } catch { /* ignore */ }
  }

  /** Token id to auto-open in the marketplace after login (set by home page card click) */
  pendingTokenId: string | null = null;
}
import { Injectable } from '@angular/core';
import * as signalR from '@microsoft/signalr';
import { environment } from '../../../environments/environment';

@Injectable({ providedIn: 'root' })
export class SignalRService {
  private hub: signalR.HubConnection | null = null;

  get connectionId(): string | null {
    return this.hub?.connectionId ?? null;
  }

  async connect(): Promise<string> {
    // Disconnect any existing hub before creating a new connection
    if (this.hub) {
      try { await this.hub.stop(); } catch { /* ignore */ }
      this.hub = null;
    }

    this.hub = new signalR.HubConnectionBuilder()
      .withUrl(`${environment.signalRHubUrl}`)
      .withAutomaticReconnect()
      .build();

    await this.hub.start();
    return this.hub.connectionId!;
  }

  on(event: string, callback: (...args: any[]) => void): void {
    this.hub?.on(event, callback);
  }

  off(event: string): void {
    this.hub?.off(event);
  }

  async disconnect(): Promise<void> {
    if (this.hub) {
      await this.hub.stop();
      this.hub = null;
    }
  }
}
import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { CheckoutFlowService, CheckoutItemResult } from '../../../core/services/checkout-flow.service';

type ViewState = 'verifying' | 'done' | 'pending';

/**
 * Landing page for the case where the embedded Flitt checkout performs a full-page redirect
 * (e.g. an external 3-D Secure step). Flitt redirects (POST) to the backend api/Payment/Return,
 * which bounces the browser here as a GET.
 *
 * The inline checkout page clears its session as soon as it has shown its own "payment complete"
 * summary. So if we arrive here with NO active session, the payment was already confirmed inline
 * and showing a summary again would just duplicate it — we go straight to the marketplace. We
 * only confirm and render a summary when a session is still active, i.e. the inline page never
 * got to finish (the genuine full-page-redirect case), so this is the single confirmation.
 */
@Component({
  selector: 'app-payment-return',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './payment-return.component.html',
  styleUrls: ['./payment-return.component.scss']
})
export class PaymentReturnComponent implements OnInit {
  state: ViewState = 'verifying';
  results: CheckoutItemResult[] = [];

  constructor(
    private checkoutFlow: CheckoutFlowService,
    private router: Router
  ) {}

  ngOnInit(): void {
    const session = this.checkoutFlow.getSession();
    if (session && session.currentOrderId) {
      this.verify();
    } else {
      // Already confirmed inline — skip the duplicate summary.
      this.router.navigate(['/marketplace']);
    }
  }

  /** Polls the order to a terminal state, then shows the summary. */
  verify(): void {
    this.state = 'verifying';
    this.checkoutFlow.resolve().subscribe({
      next: () => this.finish(),
      error: () => {
        // Timed out / couldn't confirm. Leave the session intact so the user can retry.
        this.state = 'pending';
      }
    });
  }

  private finish(): void {
    this.results = this.checkoutFlow.results();
    this.checkoutFlow.clear();
    this.state = 'done';
  }

  get successCount(): number {
    return this.results.filter(r => r.outcome === 'success').length;
  }

  get failedCount(): number {
    return this.results.filter(r => r.outcome !== 'success').length;
  }

  goToMarketplace(): void { this.router.navigate(['/marketplace']); }
  goToCart(): void { this.router.navigate(['/cart']); }
}
<div class="return-page">
  <div class="return-card">

    <!-- ── Verifying ─────────────────────────────────────── -->
    <ng-container *ngIf="state === 'verifying'">
      <div class="spinner"></div>
      <h1>Confirming your payment…</h1>
      <p>Please wait while we check the result with the bank. Don't close this page.</p>
    </ng-container>

    <!-- ── Done (summary) ────────────────────────────────── -->
    <ng-container *ngIf="state === 'done'">
      <div class="icon" [class.icon--success]="failedCount === 0" [class.icon--mixed]="failedCount > 0">
        {{ failedCount === 0 ? '✓' : '!' }}
      </div>
      <h1>{{ failedCount === 0 ? 'Payment complete' : 'Checkout finished' }}</h1>
      <p *ngIf="successCount > 0">
        {{ successCount }} token{{ successCount !== 1 ? 's' : '' }} purchased successfully.
      </p>
      <p *ngIf="failedCount > 0" class="muted">
        {{ failedCount }} item{{ failedCount !== 1 ? 's were' : ' was' }} not completed.
      </p>

      <ul class="result-list" *ngIf="results.length > 0">
        <li class="result-row" *ngFor="let r of results">
          <span class="result-row__name">{{ r.productName }}</span>
          <span class="result-row__badge"
                [class.result-row__badge--success]="r.outcome === 'success'"
                [class.result-row__badge--failed]="r.outcome !== 'success'">
            {{ r.outcome === 'success' ? 'Purchased' : (r.outcome === 'cancelled' ? 'Cancelled' : 'Failed') }}
          </span>
        </li>
      </ul>

      <div class="actions">
        <button class="btn btn--primary" (click)="goToMarketplace()">Go to Marketplace</button>
        <button class="btn btn--ghost" (click)="goToCart()">View Cart</button>
      </div>
    </ng-container>

    <!-- ── Pending / could not confirm ───────────────────── -->
    <ng-container *ngIf="state === 'pending'">
      <div class="icon icon--pending">…</div>
      <h1>Still processing</h1>
      <p>We couldn't confirm your payment yet. This can take a moment.</p>
      <div class="actions">
        <button class="btn btn--primary" (click)="verify()">Check again</button>
        <button class="btn btn--ghost" (click)="goToCart()">View Cart</button>
      </div>
    </ng-container>

  </div>
</div>

