import { Injectable } from '@angular/core';
import { Observable, throwError, timer } from 'rxjs';
import { concatMap, filter, map, take, tap, timeout } from 'rxjs/operators';
import { CartItem, CartService } from './cart.service';
import { PaymentApiService } from '../api/payment-api.service';
import {
  InitiateEmbeddedPaymentResult,
  PaymentBatchStatusResult,
  PaymentTokenRef
} from '../../shared/models/payment.model';

export interface CheckoutQueueItem {
  tokenId: string;
  rowVersion: number;
  productName: string;
  companyName: string;
  price: number;
}

export interface CheckoutItemResult {
  tokenId: string;
  productName: string;
  orderId?: string;
  outcome: 'success' | 'failed' | 'cancelled';
}

interface CheckoutSession {
  publicKey: string;
  items: CheckoutQueueItem[];
  saveCard?: boolean;
  currentOrderId?: string;
  currentToken?: string;
  results: CheckoutItemResult[];
}

/**
 * Drives an embedded Flitt checkout for the whole cart in a SINGLE payment. All primary-market
 * items are sent to the backend together, which creates one Flitt order for the summed amount
 * (one widget, one charge) while still recording each token as its own Payment row. The buyer
 * never leaves the page; the order is polled until every token reaches a terminal status. The
 * session is persisted to sessionStorage so it can be resumed if a hard redirect ever occurs
 * (e.g. an external 3-D Secure step that lands back on /payment/return).
 */
@Injectable({ providedIn: 'root' })
export class CheckoutFlowService {
  private readonly KEY = 'checkout_session';
  private readonly POLL_INTERVAL_MS = 2000;
  private readonly POLL_TIMEOUT_MS = 600000; // 10 min — buyer may be entering card / 3DS

  constructor(
    private paymentApi: PaymentApiService,
    private cart: CartService
  ) {}

  // ── session persistence ──────────────────────────────────────────────────
  getSession(): CheckoutSession | null {
    try {
      const raw = sessionStorage.getItem(this.KEY);
      return raw ? (JSON.parse(raw) as CheckoutSession) : null;
    } catch {
      return null;
    }
  }

  private save(session: CheckoutSession): void {
    try { sessionStorage.setItem(this.KEY, JSON.stringify(session)); } catch { /* ignore */ }
  }

  clear(): void {
    try { sessionStorage.removeItem(this.KEY); } catch { /* ignore */ }
  }

  // ── flow ────────────────────────────────────────────────────────────────
  /**
   * Builds a checkout session from the primary-market items in the cart.
   * Returns false if there is nothing payable (only secondary-market items, or empty).
   */
  begin(items: CartItem[], publicKey: string, saveCard: boolean = false): boolean {
    const queue: CheckoutQueueItem[] = items
      .filter(i => i.market === 'primaryMarket')
      .map(i => ({
        tokenId: i.token.id,
        rowVersion: i.token.rowVersion,
        productName: i.token.productName,
        companyName: i.token.companyName,
        price: i.token.price
      }));

    if (queue.length === 0) return false;

    this.save({ publicKey, items: queue, saveCard, results: [] });
    return true;
  }

  /** The items being paid for in the current order (for display). */
  get items(): CheckoutQueueItem[] {
    return this.getSession()?.items ?? [];
  }

  /** Number of tokens in the current order. */
  get itemCount(): number {
    return this.items.length;
  }

  /** Summed amount of the current order. */
  get total(): number {
    return this.items.reduce((sum, i) => sum + (i.price ?? 0), 0);
  }

  results(): CheckoutItemResult[] {
    return this.getSession()?.results ?? [];
  }

  /**
   * Creates the single Flitt order covering every item in the session and returns the checkout
   * token the caller renders into the embedded widget. The order id is stored for polling.
   */
  initiate(): Observable<InitiateEmbeddedPaymentResult> {
    const s = this.getSession();
    if (!s) return throwError(() => new Error('No active checkout session.'));
    if (s.items.length === 0) return throwError(() => new Error('Nothing to pay for.'));

    const tokens: PaymentTokenRef[] = s.items.map(i => ({
      serviceTokenId: i.tokenId,
      rowVersion: i.rowVersion
    }));

    return this.paymentApi
      .initiateBatch(tokens, s.publicKey, s.saveCard ?? false)
      .pipe(
        tap(res => {
          if (!res.token) throw new Error('No checkout token returned.');
          s.currentOrderId = res.orderId;
          s.currentToken = res.token;
          this.save(s);
        })
      );
  }

  /** The Flitt checkout token for the in-flight order, if any (used to (re)render the widget). */
  get currentToken(): string | null {
    return this.getSession()?.currentToken ?? null;
  }

  /** True when the order has been initiated and is awaiting a terminal status. */
  hasPendingOrder(): boolean {
    return !!this.getSession()?.currentOrderId;
  }

  /**
   * Polls the order until every token reaches a terminal status, records each token's outcome,
   * drops the purchased tokens from the cart, and completes the session.
   */
  resolve(): Observable<CheckoutItemResult[]> {
    const s = this.getSession();
    if (!s || !s.currentOrderId) {
      return throwError(() => new Error('No payment to resolve.'));
    }

    const orderId = s.currentOrderId;

    return this.pollUntilFinal(orderId).pipe(
      map(status => {
        const byToken = new Map(status.items.map(i => [i.serviceTokenId, i.status]));

        const results: CheckoutItemResult[] = s.items.map(item => {
          const itemStatus = byToken.get(item.tokenId) ?? 'Failed';
          const outcome: CheckoutItemResult['outcome'] =
            itemStatus === 'Succeeded' ? 'success'
              : itemStatus === 'Cancelled' ? 'cancelled'
                : 'failed';

          if (outcome === 'success') {
            this.cart.removeLocal(item.tokenId);
          }

          return { tokenId: item.tokenId, productName: item.productName, orderId, outcome };
        });

        s.results = results;
        s.currentOrderId = undefined;
        s.currentToken = undefined;
        this.save(s);
        return results;
      })
    );
  }

  private pollUntilFinal(orderId: string): Observable<PaymentBatchStatusResult> {
    return timer(0, this.POLL_INTERVAL_MS).pipe(
      concatMap(() => this.paymentApi.getStatus(orderId)),
      filter(r => r.final),   // stop only when every token is terminal
      take(1),                // complete on the first fully-terminal status
      timeout({ first: this.POLL_TIMEOUT_MS })
    );
  }

  /**
   * Confirms an order by id without relying on the in-memory session — used when the buyer
   * returns via a hard redirect (api/Payment/Return → ?orderId=…) and the session may be gone.
   * Builds results straight from the server's per-token breakdown; product names are taken from
   * the session when still present, otherwise a short token label is shown.
   */
  resolveByOrderId(orderId: string): Observable<CheckoutItemResult[]> {
    if (!orderId) return throwError(() => new Error('No order id to resolve.'));

    const s = this.getSession();
    const nameByToken = new Map((s?.items ?? []).map(i => [i.tokenId, i.productName]));

    return this.pollUntilFinal(orderId).pipe(
      map(status => {
        const results: CheckoutItemResult[] = status.items.map(item => {
          const outcome: CheckoutItemResult['outcome'] =
            item.status === 'Succeeded' ? 'success'
              : item.status === 'Cancelled' ? 'cancelled'
                : 'failed';

          if (outcome === 'success') {
            this.cart.removeLocal(item.serviceTokenId);
          }

          return {
            tokenId: item.serviceTokenId,
            productName: nameByToken.get(item.serviceTokenId) ?? `Token ${item.serviceTokenId}`,
            orderId,
            outcome
          };
        });

        if (s) {
          s.results = results;
          s.currentOrderId = undefined;
          s.currentToken = undefined;
          this.save(s);
        }
        return results;
      })
    );
  }
}
import { Injectable } from '@angular/core';
import { environment } from '../../../environments/environment';

/** Minimal shape of the global `checkout` function exposed by the Flitt SDK. */
type FlittCheckoutFn = (selector: string, options: FlittCheckoutOptions) => void;

declare global {
  interface Window {
    checkout?: FlittCheckoutFn;
  }
}

export interface FlittCheckoutOptions {
  options?: Record<string, unknown>;
  params: { token: string } & Record<string, unknown>;
  [key: string]: unknown;
}

/**
 * Loads the Flitt embedded-checkout SDK (JS + CSS) once and renders the checkout widget
 * into a container element. The widget keeps the buyer on our page — no redirect to
 * pay.flitt.com — and processes the order identified by the supplied checkout token.
 */
@Injectable({ providedIn: 'root' })
export class FlittCheckoutService {
  private loadPromise: Promise<void> | null = null;

  /** Ensures the SDK script + stylesheet are present, resolving once `window.checkout` exists. */
  load(): Promise<void> {
    if (window.checkout) return Promise.resolve();
    if (this.loadPromise) return this.loadPromise;

    this.loadPromise = new Promise<void>((resolve, reject) => {
      // Stylesheet (id-guarded so it is injected only once).
      if (!document.getElementById('flitt-checkout-css')) {
        const link = document.createElement('link');
        link.id = 'flitt-checkout-css';
        link.rel = 'stylesheet';
        link.href = environment.flitt.checkoutCss;
        document.head.appendChild(link);
      }

      const existing = document.getElementById('flitt-checkout-js') as HTMLScriptElement | null;
      if (existing) {
        if (window.checkout) { resolve(); return; }
        existing.addEventListener('load', () => resolve());
        existing.addEventListener('error', () => reject(new Error('Failed to load the Flitt checkout SDK.')));
        return;
      }

      const script = document.createElement('script');
      script.id = 'flitt-checkout-js';
      script.src = environment.flitt.checkoutJs;
      script.async = true;
      script.onload = () => {
        if (window.checkout) resolve();
        else reject(new Error('Flitt checkout SDK loaded but `checkout` is unavailable.'));
      };
      script.onerror = () => reject(new Error('Failed to load the Flitt checkout SDK.'));
      document.body.appendChild(script);
    });

    return this.loadPromise;
  }

  /**
   * Renders (or re-renders) the embedded checkout for the given order token into the element
   * matched by `selector`. The container is cleared first so it can host successive orders.
   */
  async render(selector: string, token: string): Promise<void> {
    await this.load();

    const container = document.querySelector(selector);
    if (container) container.innerHTML = '';

    const options: FlittCheckoutOptions = {
      options: {
        methods: ['card'],
        methods_disabled: ['wallets'],
        wallet_methods_enabled: [],        // don't init Apple/Google Pay (card-only flow)
        card_icons: ['mastercard', 'visa', 'maestro'],
        active_tab: 'card',
        full_screen: false,
        show_pay_button: true,             // (was the deprecated `button`)
        show_email: false,                 // (was the deprecated `email`)
        title: 'Service Tokens',
        theme: { type: 'light', preset: 'navy_shimmer' }
      },
      params: { token }
    };

    window.checkout!(selector, options);
  }
}
import { Component, OnInit, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { CartItem, CartService } from '../../../core/services/cart.service';
import { CheckoutFlowService, CheckoutItemResult } from '../../../core/services/checkout-flow.service';
import { FlittCheckoutService } from '../../../core/services/flitt-checkout.service';
import { InvestorStateService } from '../../../core/state/investor-state.service';
import { ToastService } from '../../../core/services/toast.service';
import { PaymentMethodApiService } from '../../../core/api/payment-method-api.service';
import { InvestorPaymentMethod } from '../../../shared/models/payment-method.model';
import { ServiceTokenDto } from '../../../shared/models/service-token.model';

type ViewState = 'loading' | 'empty' | 'summary' | 'paying' | 'pending' | 'done';

@Component({
  selector: 'app-checkout',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './checkout.component.html',
  styleUrls: ['./checkout.component.scss']
})
export class CheckoutComponent implements OnInit {
  state: ViewState = 'loading';

  payableItems: CartItem[] = [];
  secondaryItems: CartItem[] = [];

  results: CheckoutItemResult[] = [];

  /** Buyer opt-in: save the card token for faster future checkout. */
  saveCard = true;

  /** The investor's currently saved card (if any), shown on the summary. */
  savedMethod: InvestorPaymentMethod | null = null;

  private readonly CONTAINER = '#flitt-checkout';

  constructor(
    public cartService: CartService,
    private checkoutFlow: CheckoutFlowService,
    private flitt: FlittCheckoutService,
    private investorState: InvestorStateService,
    private toast: ToastService,
    private paymentMethods: PaymentMethodApiService,
    private router: Router,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    const investor = this.investorState.investor;
    if (!investor) { this.router.navigate(['/login']); return; }

    this.cartService.load(investor.publicKey).subscribe({
      next: () => this.afterCartLoaded(),
      error: () => {
        this.afterCartLoaded();           // fall back to whatever is already in memory
        this.toast.error('Could not refresh your cart.');
      }
    });
  }

  private afterCartLoaded(): void {
    this.refreshItems();
    this.loadSavedMethod();

    // Resume an in-flight order (e.g. after an external 3-D Secure redirect).
    if (this.checkoutFlow.hasPendingOrder()) {
      this.processOrder();
      return;
    }

    this.state = this.payableItems.length === 0 ? 'empty' : 'summary';
  }

  /** Loads the investor's saved card (masked) for display on the summary. Best-effort. */
  private loadSavedMethod(): void {
    const investor = this.investorState.investor;
    if (!investor) return;
    this.paymentMethods.get(investor.id).subscribe({
      next: m => {
        this.savedMethod = m?.hasSavedCard ? m : null;
        this.cdr.detectChanges();
      },
      error: () => { /* non-fatal: just don't show a saved card */ }
    });
  }

  /** Removes the saved card token for this investor. */
  removeSavedCard(): void {
    const investor = this.investorState.investor;
    if (!investor) return;
    this.paymentMethods.remove(investor.id).subscribe({
      next: () => {
        this.savedMethod = null;
        this.toast.success('Saved card removed.');
        this.cdr.detectChanges();
      },
      error: () => this.toast.error('Could not remove the saved card.')
    });
  }

  private refreshItems(): void {
    const items = this.cartService.items;
    this.payableItems = items.filter(i => i.market === 'primaryMarket');
    this.secondaryItems = items.filter(i => i.market !== 'primaryMarket');
  }

  get total(): number {
    return this.payableItems.reduce((sum, i) => sum + (i.token.price ?? 0), 0);
  }

  get currency(): string {
    // All tokens are priced in GEL on this platform.
    return 'GEL';
  }

  /** How many tokens the single payment covers (used in the 'paying' view). */
  get payingCount(): number {
    return this.checkoutFlow.itemCount;
  }

  get payingTotal(): number {
    return this.checkoutFlow.total;
  }

  pay(): void {
    const investor = this.investorState.investor;
    if (!investor) { this.router.navigate(['/login']); return; }

    const started = this.checkoutFlow.begin(this.cartService.items, investor.publicKey, this.saveCard);
    if (!started) {
      this.toast.warning('There are no payable items in your cart.');
      return;
    }
    this.processOrder();
  }

  /** Pays for the whole cart with a single embedded Flitt widget / one charge. */
  private async processOrder(): Promise<void> {
    this.state = 'paying';

    // Create the single order if we don't already have one (fresh checkout, not a resume).
    if (!this.checkoutFlow.hasPendingOrder()) {
      try {
        await firstValueFrom(this.checkoutFlow.initiate());
      } catch (err: any) {
        this.toast.error(this.errorText(err, 'Could not start the payment.'));
        this.checkoutFlow.clear();
        this.refreshItems();
        this.state = this.payableItems.length === 0 ? 'empty' : 'summary';
        return;
      }
    }

    const token = this.checkoutFlow.currentToken;
    if (token) {
      await this.renderWidget(token);
    }

    try {
      await firstValueFrom(this.checkoutFlow.resolve());
    } catch {
      // Timed out waiting for a terminal status — keep the session so the buyer can retry.
      this.state = 'pending';
      return;
    }

    this.finish();
  }

  /** Ensures the container is in the DOM, then mounts the Flitt widget into it. */
  private async renderWidget(token: string): Promise<void> {
    this.cdr.detectChanges();              // make sure #flitt-checkout is rendered
    await this.tick();
    try {
      await this.flitt.render(this.CONTAINER, token);
    } catch (err: any) {
      this.toast.error(this.errorText(err, 'Could not load the payment form.'));
    }
  }

  /** Continue polling / retry after a "pending" timeout. */
  retry(): void {
    this.processOrder();
  }

  private finish(): void {
    this.results = this.checkoutFlow.results();
    this.checkoutFlow.clear();
    this.state = 'done';
  }

  get successCount(): number {
    return this.results.filter(r => r.outcome === 'success').length;
  }

  get failedCount(): number {
    return this.results.filter(r => r.outcome !== 'success').length;
  }

  goToCart(): void { this.router.navigate(['/cart']); }
  goToMarketplace(): void { this.router.navigate(['/marketplace']); }

  pictogramSrc(token: ServiceTokenDto): string | null {
    if (!token.pictogram) return null;
    return `data:image/png;base64,${token.pictogram}`;
  }

  private tick(): Promise<void> {
    return new Promise<void>(resolve => setTimeout(resolve, 0));
  }

  private errorText(err: any, fallback: string): string {
    const detail = typeof err?.error === 'string' ? err.error : (err?.error?.message ?? err?.message);
    return detail ? `${fallback} ${detail}` : fallback;
  }
}
<div class="checkout-page">

  <!-- ── Top bar ─────────────────────────────────────────── -->
  <header class="checkout-header">
    <button class="checkout-header__back" (click)="goToCart()" [disabled]="state === 'paying'">← Back to cart</button>
    <h1 class="checkout-header__title">Checkout</h1>
  </header>

  <!-- ── Loading ─────────────────────────────────────────── -->
  <div class="checkout-state" *ngIf="state === 'loading'">
    <div class="spinner"></div>
    <p>Loading your cart…</p>
  </div>

  <!-- ── Empty ───────────────────────────────────────────── -->
  <div class="checkout-state" *ngIf="state === 'empty'">
    <div class="checkout-state__icon">🧾</div>
    <h2>Nothing to pay for</h2>
    <p>Your cart has no primary-market tokens to purchase.</p>
    <button class="btn btn--primary" (click)="goToCart()">Back to cart</button>
  </div>

  <!-- ── Order summary (ready to pay) ────────────────────── -->
  <div class="checkout-body" *ngIf="state === 'summary'">
    <section class="summary">
      <h2 class="summary__heading">Order summary</h2>

      <ul class="summary__list">
        <li class="summary__row" *ngFor="let i of payableItems">
          <div class="summary__thumb">
            <img *ngIf="pictogramSrc(i.token)" [src]="pictogramSrc(i.token)" [alt]="i.token.productName" />
            <div *ngIf="!pictogramSrc(i.token)" class="summary__thumb-placeholder">◈</div>
          </div>
          <div class="summary__info">
            <span class="summary__product">{{ i.token.productName }}</span>
            <span class="summary__company">{{ i.token.companyName }}</span>
          </div>
          <div class="summary__price">{{ i.token.price | currency:currency:'symbol':'1.2-2' }}</div>
        </li>
      </ul>

      <div class="summary__total">
        <span>Total</span>
        <span class="summary__total-value">{{ total | currency:currency:'symbol':'1.2-2' }}</span>
      </div>

      <p class="summary__note" *ngIf="secondaryItems.length > 0">
        {{ secondaryItems.length }} secondary-market item{{ secondaryItems.length !== 1 ? 's are' : ' is' }}
        not payable here and will stay in your cart.
      </p>
    </section>

    <section class="pay-panel">
      <!-- Saved card (masked) — token stored server-side; PAN is never stored or shown. -->
      <div class="saved-card" *ngIf="savedMethod as m">
        <div class="saved-card__info">
          <span class="saved-card__icon">💳</span>
          <span class="saved-card__text">
            <ng-container *ngIf="m.cardType">{{ m.cardType }} </ng-container>
            {{ m.maskedCard || 'Saved card' }}
          </span>
        </div>
        <button class="saved-card__remove" type="button" (click)="removeSavedCard()">Remove</button>
      </div>

      <label class="save-card">
        <input type="checkbox" [(ngModel)]="saveCard" />
        <span>Securely save my card for faster checkout next time</span>
      </label>

      <button class="btn btn--pay" (click)="pay()">
        Pay {{ total | currency:currency:'symbol':'1.2-2' }}
      </button>
      <p class="pay-panel__secure">
        🔒 Pay securely with your card right here — powered by Flitt. Your whole cart is charged in a single payment.
      </p>
    </section>
  </div>

  <!-- ── Paying (embedded Flitt widget) ──────────────────── -->
  <div class="checkout-body" *ngIf="state === 'paying'">
    <section class="embedded">
      <div class="embedded__progress" *ngIf="payingCount > 0">
        <span class="embedded__product">
          Paying for {{ payingCount }} token{{ payingCount !== 1 ? 's' : '' }}
        </span>
        <span class="embedded__step">
          Total {{ payingTotal | currency:currency:'symbol':'1.2-2' }}
        </span>
      </div>

      <!-- Flitt mounts its checkout form into this container; no redirect leaves the page. -->
      <div id="flitt-checkout" class="embedded__widget"></div>

      <p class="embedded__hint">
        After paying, this page confirms the result automatically — please don't close it.
      </p>
    </section>
  </div>

  <!-- ── Pending / could not confirm ─────────────────────── -->
  <div class="checkout-state" *ngIf="state === 'pending'">
    <div class="icon icon--pending">…</div>
    <h2>Still processing</h2>
    <p>We couldn't confirm your payment yet. This can take a moment.</p>
    <div class="actions">
      <button class="btn btn--primary" (click)="retry()">Check again</button>
      <button class="btn btn--ghost" (click)="goToCart()">View Cart</button>
    </div>
  </div>

  <!-- ── Done (summary) ──────────────────────────────────── -->
  <div class="checkout-state" *ngIf="state === 'done'">
    <div class="icon" [class.icon--success]="failedCount === 0" [class.icon--mixed]="failedCount > 0">
      {{ failedCount === 0 ? '✓' : '!' }}
    </div>
    <h2>{{ failedCount === 0 ? 'Payment complete' : 'Checkout finished' }}</h2>
    <p *ngIf="successCount > 0">
      {{ successCount }} token{{ successCount !== 1 ? 's' : '' }} purchased successfully.
    </p>
    <p *ngIf="failedCount > 0" class="muted">
      {{ failedCount }} item{{ failedCount !== 1 ? 's were' : ' was' }} not completed.
    </p>

    <ul class="result-list" *ngIf="results.length > 0">
      <li class="result-row" *ngFor="let r of results">
        <span class="result-row__name">{{ r.productName }}</span>
        <span class="result-row__badge"
              [class.result-row__badge--success]="r.outcome === 'success'"
              [class.result-row__badge--failed]="r.outcome !== 'success'">
          {{ r.outcome === 'success' ? 'Purchased' : (r.outcome === 'cancelled' ? 'Cancelled' : 'Failed') }}
        </span>
      </li>
    </ul>

    <div class="actions">
      <button class="btn btn--primary" (click)="goToMarketplace()">Go to Marketplace</button>
      <button class="btn btn--ghost" (click)="goToCart()">View Cart</button>
    </div>
  </div>

</div>

import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { map, tap } from 'rxjs/operators';
import { ServiceTokenDto } from '../../shared/models/service-token.model';
import { ServiceTokenApiService } from '../api/service-token-api.service';

export type CartMarket = 'primaryMarket' | 'secondaryMarket';

export interface CartItem {
  token: ServiceTokenDto;
  market: CartMarket;
}

@Injectable({ providedIn: 'root' })
export class CartService {
  private _items = new BehaviorSubject<CartItem[]>([]);
  items$ = this._items.asObservable();

  get items(): CartItem[] { return this._items.value; }
  get count(): number { return this._items.value.length; }

  constructor(private serviceTokenApi: ServiceTokenApiService) {}

  /** Loads the investor's in-cart tokens from the API and populates the local cart.
   *  Call this on app init / after login so the cart survives page refreshes. */
  load(investorPublicKey: string): Observable<void> {
    return this.serviceTokenApi.getInvestorServiceTokensInCart(investorPublicKey).pipe(
      tap((tokens: ServiceTokenDto[]) => {
        const items: CartItem[] = (tokens ?? []).map(token => ({
          token: this.normalizeToken(token),
          // Derive market from ownerType: 0 = company (primary), otherwise secondary
          market: (token.ownerType === 0 || (token as any).OwnerType === 0)
            ? 'primaryMarket'
            : 'secondaryMarket'
        }));
        this._items.next(items);
      }),
      map(() => undefined)
    );
  }

  private normalizeToken(raw: any): ServiceTokenDto {
    if (!raw) return raw;
    return {
      id:             raw.id             ?? raw.Id,
      rowVersion:     raw.rowVersion     ?? raw.RowVersion,
      companyId:      raw.companyId      ?? raw.CompanyId,
      requestId:      raw.requestId      ?? raw.RequestId,
      productId:      raw.productId      ?? raw.ProductId,
      startDate:      raw.startDate      ?? raw.StartDate,
      endDate:        raw.endDate        ?? raw.EndDate,
      status:         raw.status         ?? raw.Status,
      remainingCount: raw.remainingCount ?? raw.RemainingCount,
      serviceCount:   raw.serviceCount   ?? raw.ServiceCount,
      scheduleType:   raw.scheduleType   ?? raw.ScheduleType,
      ownerType:      raw.ownerType      ?? raw.OwnerType,
      ownerPublicKey: raw.ownerPublicKey ?? raw.OwnerPublicKey,
      companyName:    raw.companyName    ?? raw.CompanyName,
      productName:    raw.productName    ?? raw.ProductName,
      price:          raw.price          ?? raw.Price,
      pictogram:      raw.pictogram      ?? raw.Pictogram,
    };
  }

  /** Calls MarkServiceTokenInCart on the API, which returns the updated ServiceTokenDto
   *  (with the server's new RowVersion). Stores that fresh token in the cart so that
   *  CancelInCart and the checkout buy calls use the correct RowVersion. */
  add(token: ServiceTokenDto, market: CartMarket, investorPublicKey: string): Observable<void> {
    if (this._items.value.find(i => i.token?.id === token.id)) {
      return of(undefined);
    }

    return this.serviceTokenApi.markServiceTokenInCart(token.id, token.rowVersion, investorPublicKey).pipe(
      tap((updatedToken: ServiceTokenDto) => {
        // Store the returned token so we have the latest RowVersion for subsequent calls
        this._items.next([...this._items.value, { token: updatedToken, market }]);
      }),
      map(() => undefined)
    );
  }

  /** Calls CancelInCart on the API (returns updated ServiceTokenDto), then removes
   *  the token from the local cart on success. */
  remove(tokenId: string): Observable<void> {
    const item = this._items.value.find(i => i.token?.id === tokenId);
    if (!item) {
      return of(undefined);
    }

    return this.serviceTokenApi.cancelInCart(item.token.id, item.token.rowVersion).pipe(
      tap(() => {
        this._items.next(this._items.value.filter(i => i.token?.id !== tokenId));
      }),
      map(() => undefined)
    );
  }

  /** Remove from local state only — used after a successful purchase so we
   *  don't call CancelInCart for tokens that were just bought. */
  removeLocal(tokenId: string): void {
    this._items.next(this._items.value.filter(i => i.token?.id !== tokenId));
  }

  clear(): void { this._items.next([]); }

  has(tokenId: string): boolean {
    return this._items.value.some(i => i.token?.id === tokenId);
  }
}
import { Component, HostListener, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink, ActivatedRoute } from '@angular/router';

import { InvestorStateService } from '../../../core/state/investor-state.service';
import { CompanyApiService } from '../../../core/api/company-api.service';
import { ProductApiService } from '../../../core/api/product-api.service';
import { RequestApiService } from '../../../core/api/request-api.service';
import { ServiceTokenApiService } from '../../../core/api/service-token-api.service';
import { CartService, CartMarket } from '../../../core/services/cart.service';
import { ToastService } from '../../../core/services/toast.service';
import { DialogService } from '../../../core/services/dialog.service';

import { Company } from '../../../shared/models/company.model';
import { Product, ScheduleType } from '../../../shared/models/product.model';
import { Request } from '../../../shared/models/request.model';
import { ServiceTokenDto, ServiceTokenStatus } from '../../../shared/models/service-token.model';
import { GetServiceComponent, ServiceResult } from '../get-service/get-service.component';

export type MarketplaceTab = 'yourTokens' | 'primaryMarket' | 'secondaryMarket';

const TAB_KEY     = 'marketplace_active_tab';
const FILTERS_KEY = 'marketplace_filters';

@Component({
  selector: 'app-investor-marketplace',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink, GetServiceComponent],

  templateUrl: './investor-marketplace.component.html',
  styleUrls: ['./investor-marketplace.component.scss']
})
export class InvestorMarketplaceComponent implements OnInit {
  activeTab: MarketplaceTab = 'yourTokens';
  investorPublicKey = '';
  investorName = '';
  companies: Company[] = [];

  marketCompanyId = -1;
  marketProductId = -1;
  marketRequestId = -1;

  products: Product[] = [];
  allProducts: Product[] = [];

  requests: Request[] = [];
  allRequests: Request[] = [];

  yourTokens: ServiceTokenDto[] = [];
  filteredYourTokens: ServiceTokenDto[] = [];
  primaryMarketTokens: ServiceTokenDto[] = [];
  secondaryMarketTokens: ServiceTokenDto[] = [];

  loading = false;

  // Token detail modal
  detailToken: ServiceTokenDto | null = null;
  detailTab: MarketplaceTab = 'primaryMarket';

  // Get Service QR overlay
  getServiceToken: ServiceTokenDto | null = null;

  private toast = inject(ToastService);
  private dialog = inject(DialogService);

  constructor(
    private router: Router,
    private route: ActivatedRoute,
    private investorState: InvestorStateService,
    private companyApi: CompanyApiService,
    private productApi: ProductApiService,
    private requestApi: RequestApiService,
    private serviceTokenApi: ServiceTokenApiService,
    public cartService: CartService
  ) {}

  ngOnInit(): void {
    const investor = this.investorState.investor;
    if (!investor) { this.router.navigate(['/login']); return; }
    this.investorPublicKey = investor.publicKey;
    this.investorName = investor.userName;
    this.loadCompanies();
    this.loadProducts();
    this.loadRequests();
    // Restore cart from server so it survives page refreshes
    this.cartService.load(this.investorPublicKey).subscribe({
      error: err => console.error('Failed to load cart:', err)
    });

    // Check query params — e.g. from home page click after login
    this.route.queryParams.subscribe(params => {
      const tab = params['tab'] as MarketplaceTab | undefined;
      const openToken = params['openToken'] as string | undefined;

      if (tab === 'primaryMarket') {
        this.activeTab = 'primaryMarket';
        sessionStorage.setItem(TAB_KEY, 'primaryMarket');
        this.loadPrimaryMarket(false, openToken);
      } else if (tab === 'secondaryMarket') {
        this.activeTab = 'secondaryMarket';
        sessionStorage.setItem(TAB_KEY, 'secondaryMarket');
        this.loadSecondaryMarket();
      } else {
        // No query param — restore the tab the investor was on before F5
        const saved = sessionStorage.getItem(TAB_KEY) as MarketplaceTab | null;
        const restored: MarketplaceTab = (saved === 'primaryMarket' || saved === 'secondaryMarket') ? saved : 'yourTokens';
        this.activeTab = restored;
        if (restored === 'primaryMarket') this.loadPrimaryMarket();
        else if (restored === 'secondaryMarket') this.loadSecondaryMarket();
        else this.loadYourTokens();
      }
    });

    // Clear pending token after handling
    this.investorState.pendingTokenId = null;
  }

  setTab(tab: MarketplaceTab) {
    this.activeTab = tab;
    sessionStorage.setItem(TAB_KEY, tab);
    if (tab === 'yourTokens') this.loadYourTokens();
    else if (tab === 'primaryMarket') this.loadPrimaryMarket();
    else this.loadSecondaryMarket();
  }

  loadCompanies() {
    this.companyApi.getAll(0, 500, null).subscribe({
      next: list => this.companies = list ?? [],
      error: err => console.error(err)
    });
  }

  loadProducts() {
    this.productApi.getAll(0, 500, null).subscribe({
      next: list => {
        this.allProducts = list ?? [];
        this.filterProductsByCompany();
      },
      error: err => console.error(err)
    });
  }

  onCompanyChange() {
    this.marketProductId = -1;
    this.marketRequestId = -1;
    this.filterProductsByCompany();
    this.requests = [];
  }

  onProductChange() {
    this.marketRequestId = -1;
    this.filterRequestsByProduct();
  }

  private filterProductsByCompany() {
    const cId = Number(this.marketCompanyId);
    if (cId === -1) {
      this.products = [...this.allProducts];
    } else {
      this.products = this.allProducts.filter(p => Number(p.companyId) === cId);
    }
  }

  loadRequests() {
    this.requestApi.getAll(-1, 0).subscribe({
      next: list => {
        this.allRequests = list ?? [];
      },
      error: err => console.error(err)
    });
  }

  private filterRequestsByProduct() {
    const pId = Number(this.marketProductId);
    if (pId === -1) {
      this.requests = [];
    } else {
      this.requests = this.allRequests.filter(r => Number(r.productId) === pId);
    }
  }

  get isRequestFilterEnabled(): boolean {
    return Number(this.marketProductId) !== -1;
  }

  loadYourTokens(silent = false) {
    this.loading = true;
    this.serviceTokenApi.getInvestorServiceTokens(this.investorPublicKey).subscribe({
      next: list => {
        this.yourTokens = list ?? [];
        this.applyLocalYourTokensFilters();
        this.loading = false;
      },
      error: () => {
        this.loading = false;
        if (!silent) this.toast.errorWithRetry('Failed to load your tokens.', () => this.loadYourTokens());
      }
    });
  }

  applyFilters() {
    if (this.activeTab === 'yourTokens') { this.applyLocalYourTokensFilters(); return; }
    if (this.activeTab === 'primaryMarket') { this.loadPrimaryMarket(); return; }
    this.loadSecondaryMarket();
  }

  refreshFilters() {
    this.marketCompanyId = -1;
    this.marketProductId = -1;
    this.marketRequestId = -1;
    this.filterProductsByCompany();
    this.requests = [];
    this.refreshCurrentTab();
  }

  refreshCurrentTab() {
    if (this.activeTab === 'yourTokens') this.loadYourTokens();
    else if (this.activeTab === 'primaryMarket') this.loadPrimaryMarket();
    else this.loadSecondaryMarket();
  }

  private applyLocalYourTokensFilters() {
    let result = [...(this.yourTokens ?? [])];
    const cId = Number(this.marketCompanyId);
    const pId = Number(this.marketProductId);
    const rId = Number(this.marketRequestId);
    if (!isNaN(cId) && cId !== -1) result = result.filter(t => Number(t.companyId) === cId);
    if (!isNaN(pId) && pId !== -1) result = result.filter(t => Number(t.productId) === pId);
    if (!isNaN(rId) && rId !== -1) result = result.filter(t => Number(t.requestId) === rId);
    this.filteredYourTokens = result;
  }

  // ── Token detail modal ─────────────────────────────────────
  openDetail(token: ServiceTokenDto, tab: MarketplaceTab) {
    this.detailToken = token;
    this.detailTab = tab;
  }

  @HostListener('document:keydown.escape')
  onEscape() { if (this.detailToken && !this.getServiceToken) this.closeDetail(); }

  closeDetail() { this.detailToken = null; }

  addToCart(token: ServiceTokenDto) {
    // Use the modal's tab when adding from the detail view, otherwise the active grid tab.
    const tab = this.detailToken ? this.detailTab : this.activeTab;
    const market: CartMarket = tab === 'secondaryMarket' ? 'secondaryMarket' : 'primaryMarket';
    this.cartService.add(token, market, this.investorPublicKey).subscribe({
      next: () => {
        this.toast.success(`"${token.productName}" added to cart.`);
        this.closeDetail();   // dismiss the detail modal, just like the Close button
      },
      error: err => this.toast.error(err?.error?.message ?? err?.error ?? 'Failed to add token to cart.')
    });
  }

  // ── Cart ──────────────────────────────────────────────────
  openCart() { this.router.navigate(['/cart']); }

  // ── Logout ────────────────────────────────────────────────
  async logout() {
    const confirmed = await this.dialog.confirm({
      title: 'Log Out',
      message: 'Are you sure you want to log out?',
      confirmText: 'Log Out',
      cancelText: 'Cancel',
      type: 'warning'
    });
    if (!confirmed) return;
    this.investorState.investor = null;
    this.cartService.clear();
    sessionStorage.removeItem(TAB_KEY);
    this.router.navigate(['/login'], { replaceUrl: true });
  }

  // ── Get Service QR overlay ─────────────────────────────────
  openGetService(t: ServiceTokenDto) { this.getServiceToken = t; }

  onGetServiceClosed(result: ServiceResult | null) {
    this.getServiceToken = null;
    if (!result) return;
    if (result.success) {
      this.toast.success('Service granted successfully!');
      this.loadYourTokens(true);
    } else {
      this.toast.error(result.message ?? 'Service request failed.');
      this.loadYourTokens(true);
    }
  }

  // ── Mark / Cancel ─────────────────────────────────────────────────────────────────────────
  markForResell(t: ServiceTokenDto, event?: Event) {
    event?.stopPropagation();
    this.loading = true;
    this.serviceTokenApi.markServiceTokenForResell(t.id, t.rowVersion).subscribe({
      next: _ => { this.loading = false; this.toast.success('Token marked for resell.'); this.loadYourTokens(true); },
      error: err => { this.loading = false; this.toast.error(err.error?.message ?? err.error); }
    });
  }

  cancelReselling(t: ServiceTokenDto, event?: Event) {
    event?.stopPropagation();
    this.loading = true;
    this.serviceTokenApi.cancelReselling(t.id, t.rowVersion).subscribe({
      next: _ => { this.loading = false; this.toast.success('Reselling cancelled.'); this.loadYourTokens(true); },
      error: err => { this.loading = false; this.toast.error(err.error?.message ?? err.error); }
    });
  }

  loadPrimaryMarket(silent = false, openTokenId?: string) {
    this.loading = true;
    this.serviceTokenApi.getPrimaryMarketServiceTokens(this.marketCompanyId, this.marketRequestId).subscribe({
      next: list => {
        this.primaryMarketTokens = list ?? [];
        this.loading = false;
        if (openTokenId) {
          const t = this.primaryMarketTokens.find(x => x.id === openTokenId);
          if (t) this.openDetail(t, 'primaryMarket');
        }
      },
      error: () => { this.loading = false; if (!silent) this.toast.errorWithRetry('Failed to load primary market.', () => this.loadPrimaryMarket()); }
    });
  }

  loadSecondaryMarket(silent = false) {
    this.loading = true;
    this.serviceTokenApi.getSecondaryMarketServiceTokens(this.investorPublicKey, this.marketCompanyId, this.marketRequestId).subscribe({
      next: list => { this.secondaryMarketTokens = list ?? []; this.loading = false; },
      error: () => { this.loading = false; if (!silent) this.toast.errorWithRetry('Failed to load secondary market.', () => this.loadSecondaryMarket()); }
    });
  }

  // ── Filtered token lists (exclude items already in cart) ──
  get visiblePrimaryTokens(): ServiceTokenDto[] {
    let tokens = this.primaryMarketTokens.filter(t => !this.cartService.has(t.id));
    const pId = Number(this.marketProductId);
    if (!isNaN(pId) && pId !== -1) tokens = tokens.filter(t => Number(t.productId) === pId);
    return tokens;
  }

  get visibleSecondaryTokens(): ServiceTokenDto[] {
    let tokens = this.secondaryMarketTokens.filter(t => !this.cartService.has(t.id));
    const pId = Number(this.marketProductId);
    if (!isNaN(pId) && pId !== -1) tokens = tokens.filter(t => Number(t.productId) === pId);
    return tokens;
  }

  // ── Display helpers ────────────────────────────────────────
  statusClass(status: number): string {
    switch (status) {
      case ServiceTokenStatus.None:      return 'badge--gray';
      case ServiceTokenStatus.Available: return 'badge--green';
      case ServiceTokenStatus.Sold:      return 'badge--blue';
      case ServiceTokenStatus.InCart:    return 'badge--yellow';
      case ServiceTokenStatus.Finished:  return 'badge--gray';
      default:                           return 'badge--gray';
    }
  }

  tokenStatusLabel(status: number): string {
    switch (status) {
      case ServiceTokenStatus.None:      return 'None';
      case ServiceTokenStatus.Available: return 'Available';
      case ServiceTokenStatus.Sold:      return 'Sold';
      case ServiceTokenStatus.InCart:    return 'In Cart';
      case ServiceTokenStatus.Finished:  return 'Finished';
      default: return `Status ${status}`;
    }
  }

  scheduleTypeLabel(st: ScheduleType): string {
    if (!st) return '—';
    const base = this.schedulePeriodLabel(st.periodType);
    if (st.periodType === 0) return base;
    return st.periodNumber > 0 ? `${base} / ${st.periodNumber}` : base;
  }

  private schedulePeriodLabel(v: number): string {
    switch (v) {
      case 0: return 'Free use';  case 1: return 'Daily';
      case 2: return 'Weekly'; case 3: return 'Monthly';
      case 4: return 'Yearly'; default: return `Period ${v}`;
    }
  }

  pictogramSrc(token: ServiceTokenDto): string | null {
    if (!token.pictogram) return null;
    return `data:image/png;base64,${token.pictogram}`;
  }
}
<!-- ═══ TOP APP BAR ═════════════════════════════════════════ -->
<header class="app-bar">
  <div class="app-bar__inner">
    <div class="app-bar__brand">
      <span class="app-bar__logo">◈</span>
      <span class="app-bar__title">Marketplace</span>
    </div>
    <div class="app-bar__meta">
      <button class="app-bar__refresh" (click)="refreshCurrentTab()" [disabled]="loading" aria-label="Refresh">
        <span [class.spinning]="loading">↻</span>
      </button>
      <span class="app-bar__key" title="{{ investorPublicKey }}">{{ investorName }}</span>
      <button class="logout-btn" (click)="logout()" title="Log out"><span aria-hidden="true">⏻</span> Log Out</button>
    </div>
  </div>

  <!-- Tab bar -->
  <div class="desktop-tabs">
    <button class="desktop-tab" [class.desktop-tab--active]="activeTab === 'yourTokens'" (click)="setTab('yourTokens')">
      My Tokens
    </button>
    <button class="desktop-tab" [class.desktop-tab--active]="activeTab === 'primaryMarket'" (click)="setTab('primaryMarket')">
      Primary Market
    </button>
    <button class="desktop-tab" [class.desktop-tab--active]="activeTab === 'secondaryMarket'" (click)="setTab('secondaryMarket')">
      Secondary Market
    </button>

    <!-- Cart button — right side -->
    <div class="desktop-tabs__spacer"></div>
    <button class="cart-btn" (click)="openCart()">
      🛒 Cart
      <span class="cart-btn__badge" *ngIf="cartService.count > 0">{{ cartService.count }}</span>
    </button>
  </div>

  <!-- Filter bar -->
  <div class="filter-bar">
    <label class="filter-bar__field">
      <span class="filter-bar__label">Company</span>
      <select [(ngModel)]="marketCompanyId" class="filter-bar__input" (ngModelChange)="onCompanyChange()">
        <option [ngValue]="-1">All companies</option>
        <option *ngFor="let c of companies" [ngValue]="c.id">{{ c.name }}</option>
      </select>
    </label>
    <label class="filter-bar__field">
      <span class="filter-bar__label">Product</span>
      <select [(ngModel)]="marketProductId" class="filter-bar__input" (ngModelChange)="onProductChange()">
        <option [ngValue]="-1">All products</option>
        <option *ngFor="let p of products" [ngValue]="p.id">{{ p.name }}</option>
      </select>
    </label>
    <label class="filter-bar__field">
      <span class="filter-bar__label">Request</span>
      <select [(ngModel)]="marketRequestId" class="filter-bar__input" [disabled]="!isRequestFilterEnabled">
        <option [ngValue]="-1">All requests</option>
        <option *ngFor="let r of requests" [ngValue]="r.id">{{ r.id }} — {{ r.productName }}</option>
      </select>
    </label>
    <button class="filter-bar__btn filter-bar__btn--primary" (click)="applyFilters()">Apply</button>
    <button class="filter-bar__btn" (click)="refreshFilters()">Reset</button>
  </div>
</header>

<!-- ═══ LOADING INDICATOR ════════════════════════════════════ -->
<div class="loading-bar" *ngIf="loading" role="status" aria-label="Loading"></div>

<!-- ═══ MAIN CONTENT ════════════════════════════════════════ -->
<main class="main-content">

  <!-- ── My Tokens ──────────────────────────────────────── -->
  <section *ngIf="activeTab === 'yourTokens'" class="tab-content">
    <div class="card-grid">
      <div class="token-card" *ngFor="let t of filteredYourTokens" (click)="openDetail(t, 'yourTokens')">
        <div class="token-card__image">
          <img *ngIf="pictogramSrc(t)" [src]="pictogramSrc(t)" [alt]="t.productName" />
          <div *ngIf="!pictogramSrc(t)" class="token-card__image-placeholder">◈</div>
        </div>
        <div class="token-card__header">
          <span class="token-card__company">{{ t.companyName }}</span>
          <span class="badge" [class]="statusClass(t.status)">{{ tokenStatusLabel(t.status) }}</span>
        </div>
        <div class="token-card__product">{{ t.productName }}</div>
        <div class="token-card__body">
          <div class="token-card__stat">
            <span class="token-card__stat-label">Remaining service count</span>
            <span class="token-card__stat-value">{{ t.remainingCount }}</span>
          </div>
          <div class="token-card__stat">
            <span class="token-card__stat-label">Total service count</span>
            <span class="token-card__stat-value">{{ t.serviceCount }}</span>
          </div>
          <div class="token-card__stat-row">
            <div class="token-card__stat">
              <span class="token-card__stat-label">Start date</span>
              <span class="token-card__stat-value">{{ t.startDate | date:'mediumDate' }}</span>
            </div>
            <div class="token-card__stat">
              <span class="token-card__stat-label">End date</span>
              <span class="token-card__stat-value">{{ t.endDate ? (t.endDate | date:'mediumDate') : '—' }}</span>
            </div>
          </div>
        </div>
        <div class="token-card__footer">
          <span class="token-card__id">Token #{{ t.id | slice:0:8 }}…</span>
          <div class="token-card__actions" (click)="$event.stopPropagation()">
            <button *ngIf="+t.status === 2" class="tc-btn tc-btn--sm tc-btn--green"
              (click)="openGetService(t)">Get Service</button>
            <button *ngIf="+t.status === 2" class="tc-btn tc-btn--sm tc-btn--outline"
              (click)="markForResell(t)">Resell</button>
            <button *ngIf="+t.status === 1" class="tc-btn tc-btn--sm tc-btn--warn"
              (click)="cancelReselling(t)">Cancel Resell</button>
          </div>
        </div>
      </div>
    </div>
    <p class="empty-msg" *ngIf="!loading && filteredYourTokens.length === 0">No tokens found.</p>
  </section>

  <!-- ── Primary Market ───────────────────────────────────── -->
  <section *ngIf="activeTab === 'primaryMarket'" class="tab-content">
    <div class="card-grid">
      <div class="token-card token-card--buyable token-card--primary" *ngFor="let t of visiblePrimaryTokens"
           (click)="openDetail(t, 'primaryMarket')">
        <div class="token-card__image">
          <img *ngIf="pictogramSrc(t)" [src]="pictogramSrc(t)" [alt]="t.productName" />
          <div *ngIf="!pictogramSrc(t)" class="token-card__image-placeholder">◈</div>
        </div>
        <div class="token-card__header">
          <span class="token-card__company">{{ t.companyName }}</span>
          <span class="badge badge--green">Available</span>
        </div>
        <div class="token-card__product">{{ t.productName }}</div>
        <div class="token-card__body">
          <div class="token-card__stat">
            <span class="token-card__stat-label">Total service count</span>
            <span class="token-card__stat-value">{{ t.serviceCount }}</span>
          </div>
          <div class="token-card__stat token-card__stat--full" *ngIf="t.term != null">
            <span class="token-card__stat-label">Term</span>
            <span class="token-card__stat-value">{{ t.term }} - Months</span>
          </div>
          <div class="token-card__stat token-card__stat--full">
            <span class="token-card__stat-label">Schedule</span>
            <span class="token-card__stat-value">{{ scheduleTypeLabel(t.scheduleType) }}</span>
          </div>
        </div>
        <div class="token-card__footer">
          <span class="token-card__id">Token #{{ t.id | slice:0:8 }}…</span>
          <div class="token-card__actions" (click)="$event.stopPropagation()">
            <button class="tc-btn tc-btn--sm tc-btn--outline"
              [class.tc-btn--in-cart]="cartService.has(t.id)"
              [disabled]="cartService.has(t.id)"
              (click)="addToCart(t)">
              {{ cartService.has(t.id) ? '✓ In Cart' : '🛒 Cart' }}
            </button>
          </div>
        </div>
      </div>
    </div>
    <p class="empty-msg" *ngIf="!loading && visiblePrimaryTokens.length === 0">No tokens available.</p>
  </section>

  <!-- ── Secondary Market ─────────────────────────────────── -->
