  private counter = 0;
  readonly toasts = signal<Toast[]>([]);

  private show(type: ToastType, message: string, options: ToastOptions = {}): void {
    const id = `toast-${++this.counter}`;
    const duration = options.duration ?? (type === 'error' ? 5000 : 3000);
