  try { await fn(page, fx, vp); }
  catch (e) { check(`${name}@${vp.w} scenario completed`, false, e.message.split('\n').slice(0, 6).join(' / ').slice(0, 700)); try { await shot(page, 'ERR-' + name, vp, 'scenario-error'); } catch { } }
