        const ab = await page.locator('.action-bar__btn').evaluateAll(b => b.map(x => Math.round(x.getBoundingClientRect().height)));
        check(`token-${name}@${vp.w} action buttons >= 44px`, ab.every(h => h >= 44), JSON.stringify(ab));
