const L = require('./lib.cjs');
(async () => {
  const srv = await L.startServer();
  const b = await L.chromium.launch({ executablePath: L.CHROME, headless: true });
  const vp = L.VIEWPORTS[0]; const fx = L.baseFx();
  fx.cart = [{ token: { ...fx.primary[0], status: 3 } }, { token: { ...fx.primary[1], status: 3 } }, { token: { ...fx.secondary[0], status: 3 } }];
  const ctx = await L.newCtx(b, vp, fx); const page = await ctx.newPage(); await L.attach(page, fx); await L.loginViaStorage(page, fx);
  await page.goto(L.BASE + '/checkout'); await page.waitForSelector('.saved-card__remove');
  for (let i = 0; i < 6; i++) {
    console.log(JSON.stringify(await page.evaluate(() => { const e = document.querySelector('.saved-card__remove'); const r = e.getBoundingClientRect(); const cs = getComputedStyle(e); return { r: [r.x, r.y, r.width, r.height], anim: cs.animationName, tr: cs.transform, sy: scrollY, ih: innerHeight, sc: document.scrollingElement.scrollHeight }; })));
    await new Promise(r => setTimeout(r, 300));
  }
  await page.screenshot({ path: 'docs/design-blue/screenshots/_debug_checkout360.png', fullPage: true });
  await b.close(); srv.stop();
