      const tok = { ...fx.mine[0], status: 1 };
      await openTokenPage(page, tok, 'yourTokens', fx.investor.publicKey);
      await page.locator('.action-bar__btn', { hasText: 'Get Service' }).click(); await page.waitForSelector('.qr-modal__qr-img', { timeout: 8000 }); await sleep(300);
