    for (const [route, setup, label] of [['/login', null, 'login'], ['/marketplace', null, 'marketplace'], ['/cart', cartSetup, 'cart'], ['/', null, 'home']]) {
      await run('focus-' + label, VIEWPORTS[2], setup, async (page, fx, vp) => {
