  const f = R.checks.filter(c => !c.ok);
  console.log(`\nDONE checks=${R.checks.length} pass=${R.checks.length - f.length} fail=${f.length} shots=${R.shots.length}`);
})().catch(e => { console.error('HARNESS ERROR', e); process.exit(2); });

